-- ═══════════════════════════════════════════════════════════════
-- SOLTEX — Supabase Schema
-- Alefaso ao amin'ny Supabase Dashboard > SQL Editor > New query
-- avy eo tsindrio "Run" (indray mandeha ihany no ilaina, raha vao
-- misy ny site)
-- ═══════════════════════════════════════════════════════════════

-- 1) PRODUITS — takelaka mitahiry ny catalogue (izay teo amin'ny
--    javacript.js taloha dia hafindra eto mba ho azo ovaina
--    tsy misy code, avy amin'ny Supabase Dashboard mihitsy)
create table if not exists products (
  id           integer primary key,
  name         text not null,
  cat          text not null,
  type         text,
  icon         text,
  imgs         jsonb not null default '[]',
  price        numeric not null,
  old_price    numeric,
  badge        text,
  description  text,
  specs        jsonb not null default '[]',
  feats        jsonb not null default '[]',
  created_at   timestamptz not null default now()
);

-- 2) COMMANDES — isaky ny "commande" ataon'ny mpividy
create table if not exists orders (
  id               uuid primary key default gen_random_uuid(),
  ref              text not null,
  prenom           text not null,
  nom              text not null,
  tel              text not null,
  adresse          text not null,
  ville            text not null,
  code_postal      text,
  payment_method   text not null,
  payment_number   text,
  subtotal         numeric not null,
  shipping         numeric not null default 0,
  total            numeric not null,
  status           text not null default 'en_attente',
  created_at       timestamptz not null default now()
);

-- 3) LIGNES DE COMMANDE — ny entana isaky ny commande
create table if not exists order_items (
  id            uuid primary key default gen_random_uuid(),
  order_id      uuid not null references orders(id) on delete cascade,
  product_id    integer,
  product_name  text not null,
  unit_price    numeric not null,
  qty           integer not null,
  created_at    timestamptz not null default now()
);

-- 4) MESSAGES — ny formulaire "Contact"
create table if not exists contact_messages (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  tel         text not null,
  email       text not null,
  subject     text,
  message     text not null,
  created_at  timestamptz not null default now()
);

-- ── SECURITE (Row Level Security) ──
-- Manokatra ny RLS amin'ny tabilao rehetra, ary ny "anon key" (izay
-- apetraka eo amin'ny site, hita amin'ny olona rehetra) dia:
--   - mahazo MAMAKY ("select") ny produits fotsiny
--   - mahazo MANAMPY ("insert") commande/message vaovao ihany, TSY
--     mahazo mamaky/manova/mamafa ny commande na message an'ny hafa
alter table products enable row level security;
alter table orders enable row level security;
alter table order_items enable row level security;
alter table contact_messages enable row level security;

drop policy if exists "products_public_read" on products;
create policy "products_public_read" on products
  for select to anon using (true);

drop policy if exists "orders_public_insert" on orders;
create policy "orders_public_insert" on orders
  for insert to anon with check (true);

drop policy if exists "order_items_public_insert" on order_items;
create policy "order_items_public_insert" on order_items
  for insert to anon with check (true);

drop policy if exists "contact_public_insert" on contact_messages;
create policy "contact_public_insert" on contact_messages
  for insert to anon with check (true);

-- Fanamarihana: raha te-hijery ny commande/message ianao (Tanjona /
-- ny tompon'ny tranokala), ampiasao ny Supabase Dashboard > Table
-- Editor mivantana — mampiasa ny "service role" izy io ka mihoatra
-- ny RLS voafetra etsy ambony.

